INSERT INTO filmes (titulo, descricao, imagem_url, categoria, ano_lancamento) VALUES
('Breaking Bad', 'Um professor de química do ensino médio diagnosticado com câncer de pulmão terminal se junta a um ex-aluno para fabricar e vender metanfetamina.', 'https://images.unsplash.com/photo-1594909122845-11baa439b7bf?q=80&w=400', 'Série / Drama', 2008),
('Interstellar', 'Uma equipe de exploradores viaja através de um buraco de minhoca no espaço na tentativa de garantir a sobrevivência da humanidade.', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=400', 'Filme / Ficção Científica', 2014),
('Dark', 'O desaparecimento de duas crianças pequenas em uma cidade alemã expõe os relacionamentos fraturados e as vidas duplas entre quatro famílias.', 'https://images.unsplash.com/photo-1509114397022-ed747cca3f65?q=80&w=400', 'Série / Suspense', 2017),
('The Matrix', 'Um hacker de computador aprende com rebeldes misteriosos sobre a verdadeira natureza de sua realidade e seu papel na guerra contra seus controladores.', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?q=80&w=400', 'Filme / Ação', 1999),
('Black Mirror', 'Uma série de antologia que explora um mundo de alta tecnologia retorcido e próximo, onde as maiores inovações da humanidade e os instintos mais sombrios colidem.', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?q=80&w=400', 'Série / Sci-Fi', 2011),
('Gladiador', 'Um ex-general romano busca vingança contra o imperador corrupto que assassinou sua família e o enviou para a escravidão.', 'https://images.unsplash.com/photo-1558591710-4b4a1ae0f04d?q=80&w=400', 'Filme / Épico', 2000),
('Better Call Saul', 'As provações e tribulações do advogado criminalista Jimmy McGill nos anos que antecederam o estabelecimento de seu escritório de advocacia em Albuquerque.', 'https://images.unsplash.com/photo-1589829545856-d10d557cf95f?q=80&w=400', 'Série / Drama', 2015),
('O Senhor dos Anéis', 'Um manso Hobbit do Condado e oito companheiros partem em uma jornada para destruir o poderoso Um Anel e salvar a Terra-média do Senhor das Trevas Sauron.', 'https://images.unsplash.com/photo-1461360370896-922624d12aa1?q=80&w=400', 'Filme / Fantasia', 2001),
('Peaky Blinders', 'Uma epopeia de gângsteres ambientada nas ruas sem lei de Birmingham na década de 1920, centrada em uma família que comanda uma organização criminosa.', 'https://images.unsplash.com/photo-1510519138101-570d1dca3d66?q=80&w=400', 'Série / Policial', 2013),
('Duna', 'Adaptação mítica e emocionante da jornada de Paul Atreides, um jovem brilhante e talentoso nascido para um grande destino além de sua compreensão.', 'https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?q=80&w=400', 'Filme / Ficção Científica', 2021),
('Mindhunter', 'Dois agentes do FBI expandem a ciência criminal nos anos 1970 ao mergulhar na psicologia do assassinato e se aproximar de monstros reais.', 'https://images.unsplash.com/photo-1578328819058-b69f3a3b0f6b?q=80&w=400', 'Série / Suspense', 2017),
('Parasita', 'A ganância e a discriminação de classe ameaçam o relacionamento recém-formado entre a rica família Park e o clã Kim, que vive na miséria.', 'https://images.unsplash.com/photo-1535498730771-e735b998cd64?q=80&w=400', 'Filme / Suspense', 2019),
('Severance', 'Mark lidera uma equipe de funcionários de escritório cujas memórias foram divididas cirurgicamente entre suas vidas profissionais e pessoais.', 'https://images.unsplash.com/photo-1497366216548-37526070297c?q=80&w=400', 'Série / Mistério', 2022),
('O Cavaleiro das Trevas', 'Quando a ameaça conhecida como O Coringa surge de seu passado, ela causa estragos e caos no povo de Gotham.', 'https://images.unsplash.com/photo-1534447677768-be436bb09401?q=80&w=400', 'Filme / Ação', 2008),
('Succession', 'A saga da família Roy, que controla um dos maiores conglomerados de mídia e entretenimento do mundo, e a disputa pelo poder após o patriarca se afastar.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?q=80&w=400', 'Série / Drama', 2018),
('Mad Max: Estrada da Fúria', 'Em um futuro pós-apocalíptico, uma mulher se rebela contra um governante tirânico em busca de sua terra natal com a ajuda de um andarilho chamado Max.', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?q=80&w=400', 'Filme / Ação', 2015),
('The Last of Us', 'Após uma pandemia global destruir a civilização, um sobrevivente endurecido assume a responsabilidade de cuidar de uma menina de 14 anos que pode ser a última esperança da humanidade.', 'https://images.unsplash.com/photo-1568605117036-5fe5e7bab0b7?q=80&w=400', 'Série / Drama', 2023),
('Spider-Man: No Way Home', 'Com a identidade do Homem-Aranha revelada, Peter pede ajuda ao Doutor Estranho. Quando um feitiço dá errado, inimigos perigosos de outros mundos começam a aparecer.', 'https://images.unsplash.com/photo-1608889174637-3c44f6326f1a?q=80&w=400', 'Filme / Heróis', 2021),
('Chernobyl', 'Em abril de 1986, uma enorme explosão irrompe na Usina Nuclear de Chernobyl, na União Soviética, contando as histórias daqueles que sacrificaram tudo para salvar a Europa.', 'https://images.unsplash.com/photo-1517486808906-6ca8b3f04846?q=80&w=400', 'Série / Histórico', 2019),
('Bastardos Inglórios', 'Na França ocupada pelos nazistas durante a Segunda Guerra Mundial, um plano para assassinar líderes nazistas por um grupo de soldados judeus dos EUA coincide com os planos vingativos de uma dona de cinema.', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?q=80&w=400', 'Filme / Guerra', 2009);